	sealed class RefDataRepoSenderTest : TestCaseWithFactory
	{
		public void TestSendIfNeeded()
		{
			EDIMessage message = null;
			RefDataRepoSender.SendIfNeeded(message, "TESTSOURCE", RefDataRepoSender.ContentType.Edifact);
			var query = new ZQuery(EDIInterchangeSchema.EI_ApplicationCode, EDIInterchangeTypeList.Codes.GenericMessageDelivery);
			query.FetchOnlyFromLocalCache = true;
			AssertNull(Factory.LoadTop1<EDIInterchange>(query));
			message = Factory.New<EDIMessage>();
			message.EM_MessageText = "HELLO WORLD > BYE";
			message.EM_Status = EDIMessage.Status.Received;
			using (SGCustomsDataRegistry.Instance.SendTestMessages.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				RefDataRepoSender.SendIfNeeded(message, "TESTSOURCE", RefDataRepoSender.ContentType.Edifact);
				AssertNull(Factory.LoadTop1<EDIInterchange>(query));
			}

			using (SGCustomsDataRegistry.Instance.SendTestMessages.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				RefDataRepoSender.SendIfNeeded(message, "TESTSOURCE", RefDataRepoSender.ContentType.Edifact);
				var interchange = Factory.LoadTop1<EDIInterchange>(query);
				AssertContains("Generation for RefDataRepo should indicate edifact message", "<ContentType>EDF</ContentType>", interchange.EI_BodyText);
				AssertInterchange(interchange, "CUSTOMS_DATA_REPO_TEST", "RDM", @"<RefDbRepoMessage><Source>SG</Source><SubSource>TESTSOURCE</SubSource><ContentType>EDF</ContentType><Data>HELLO WORLD &gt; BYE</Data></RefDbRepoMessage>");
			}
		}

