		public static void AssertInterchange(EDIInterchange interchange, ZString recipient, ZString interchangeType, ZString bodyText)
		{
			CombineAssertions(() =>
			{
				AssertEquals("interchange.EI_ApplicationCode", EDIInterchange.ApplicationCodes.GenericMessageDelivery, interchange.EI_ApplicationCode);
				AssertEquals("interchange.EI_InterchangeType", interchangeType, interchange.EI_InterchangeType);
				AssertEquals("interchange.EI_ReceiveTransmit", EDIInterchange.Direction.Transmit, interchange.EI_ReceiveTransmit);
				AssertEquals("interchange.EI_From", GlbCompany.CurrentCompany.LicenceKeyIdentifier, interchange.EI_From);
				AssertEquals("interchange.EI_To", recipient, interchange.EI_To);
				AssertEquals("interchange.EI_Status", EDIInterchange.Status.eHubQueued, interchange.EI_Status);
				AssertMultilineASCIIEquals("interchange.EI_BodyText", bodyText, interchange.EI_BodyText);
				AssertNotEquals("interchange.EI_SessionGUID", ZGuid.Empty, interchange.EI_SessionGUID);
			}

			);
		}
	}
